#include <zephyr/ztest.h>
#include <zephyr/net/socket.h>
#include <zephyr/net/http_client.h>
#include <zephyr/net/net_mgmt.h>
#include <zephyr/net/net_event.h>
#include <string.h>
#include <stdio.h>

#define SERVER_PORT 8080
#define SERVER_ADDR "127.0.0.1"

/* Test context for callbacks */
struct test_ctx {
    struct k_sem sem;
    int status_code;
    size_t offset; /* Total body bytes received (for verification in some tests) */
    bool headers_received;
    bool body_received;
    bool finished;
    char *expected_body;
    size_t expected_body_len;
};

/* --- Server setup --- */
static int dummy_server_fd = -1;
static struct sockaddr_in server_addr;
static struct k_thread server_thread;
static K_THREAD_STACK_DEFINE(server_stack, 2048);

#define CHUNKED_BODY_PART1 "Hello"
#define CHUNKED_BODY_PART2 "World"
#define CHUNKED_BODY_PART3 "!"
#define CHUNKED_BODY_FULL CHUNKED_BODY_PART1 CHUNKED_BODY_PART2 CHUNKED_BODY_PART3

/* Fix: Ensure CHUNKED_BODY_SIZE correctly reflects the length of the string literal.
 * sizeof("string") includes the null terminator, so we subtract 1 to get the actual length.
 */
#define CHUNKED_BODY_SIZE (sizeof(CHUNKED_BODY_FULL) - 1)

static void server_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    int client_fd;
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char rx_buf[256];
    int rcvd_bytes;

    dummy_server_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    zassert_true(dummy_server_fd >= 0, "Failed to create server socket");

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    inet_pton(AF_INET, SERVER_ADDR, &server_addr.sin_addr);

    int ret = bind(dummy_server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    zassert_equal(ret, 0, "Failed to bind server socket");

    ret = listen(dummy_server_fd, 1);
    zassert_equal(ret, 0, "Failed to listen on server socket");

    while (true) {
        client_fd = accept(dummy_server_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd < 0) {
            if (errno == EINTR || errno == EAGAIN) {
                continue;
            }
            break; /* Error or server shutdown */
        }

        rcvd_bytes = recv(client_fd, rx_buf, sizeof(rx_buf) - 1, 0);
        if (rcvd_bytes > 0) {
            rx_buf[rcvd_bytes] = '\0';
            /* Check if it's a GET request for chunked body */
            if (strstr(rx_buf, "GET /chunked HTTP/1.1") != NULL) {
                const char *response_headers =
                    "HTTP/1.1 200 OK\r\n"
                    "Transfer-Encoding: chunked\r\n"
                    "Content-Type: text/plain\r\n"
                    "\r\n";
                send(client_fd, response_headers, strlen(response_headers), 0);

                /* Send chunked body */
                char chunk_len_str[10];
                int len;

                len = strlen(CHUNKED_BODY_PART1);
                snprintk(chunk_len_str, sizeof(chunk_len_str), "%x\r\n", len);
                send(client_fd, chunk_len_str, strlen(chunk_len_str), 0);
                send(client_fd, CHUNKED_BODY_PART1, len, 0);
                send(client_fd, "\r\n", 2, 0);

                len = strlen(CHUNKED_BODY_PART2);
                snprintk(chunk_len_str, sizeof(chunk_len_str), "%x\r\n", len);
                send(client_fd, chunk_len_str, strlen(chunk_len_str), 0);
                send(client_fd, CHUNKED_BODY_PART2, len, 0);
                send(client_fd, "\r\n", 2, 0);

                len = strlen(CHUNKED_BODY_PART3);
                snprintk(chunk_len_str, sizeof(chunk_len_str), "%x\r\n", len);
                send(client_fd, chunk_len_str, strlen(chunk_len_str), 0);
                send(client_fd, CHUNKED_BODY_PART3, len, 0);
                send(client_fd, "\r\n", 2, 0);

                /* Last chunk */
                send(client_fd, "0\r\n\r\n", 5, 0);
            } else if (strstr(rx_buf, "GET /no_resource HTTP/1.1") != NULL) {
                const char *response = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n";
                send(client_fd, response, strlen(response), 0);
            } else if (strstr(rx_buf, "GET /status_cb HTTP/1.1") != NULL) {
                const char *response = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
                send(client_fd, response, strlen(response), 0);
            } else if (strstr(rx_buf, "GET /headers_cb HTTP/1.1") != NULL) {
                const char *response = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nX-Test-Header: Value\r\n\r\n";
                send(client_fd, response, strlen(response), 0);
            } else if (strstr(rx_buf, "POST /post HTTP/1.1") != NULL) {
                /* Read body, then respond */
                const char *response = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
                send(client_fd, response, strlen(response), 0);
            } else if (strstr(rx_buf, "POST /post_payload_cb HTTP/1.1") != NULL) {
                /* Read body, then respond */
                const char *response = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
                send(client_fd, response, strlen(response), 0);
            }
        }
        close(client_fd);
    }
    close(dummy_server_fd);
    dummy_server_fd = -1;
}

static void start_dummy_server(void)
{
    k_thread_create(&server_thread, server_stack, K_THREAD_STACK_SIZE(server_stack),
                    server_thread_entry, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_NO_WAIT);
    k_thread_name_set(&server_thread, "http_server");
    k_sleep(K_MSEC(100)); /* Give server time to start */
}

static void stop_dummy_server(void)
{
    if (dummy_server_fd >= 0) {
        close(dummy_server_fd);
        dummy_server_fd = -1;
    }
    k_thread_abort(&server_thread);
}

/* --- HTTP Client Callbacks --- */
static void http_client_test_cb(struct http_client_ctx *ctx,
                                enum http_client_evt type,
                                void *user_data)
{
    struct test_ctx *test_ctx = (struct test_ctx *)user_data;

    switch (type) {
    case HTTP_CLIENT_EVT_STATUS_CODE:
        test_ctx->status_code = ctx->http_status_code;
        break;
    case HTTP_CLIENT_EVT_RECV_HEADERS:
        test_ctx->headers_received = true;
        break;
    case HTTP_CLIENT_EVT_RECV_BODY:
        test_ctx->body_received = true;
        /* The ctx->offset is managed by the http_client library itself.
         * The test verifies its final value.
         */
        break;
    case HTTP_CLIENT_EVT_DISCONNECTED:
        test_ctx->finished = true;
        k_sem_give(&test_ctx->sem);
        break;
    case HTTP_CLIENT_EVT_NONE:
    case HTTP_CLIENT_EVT_SENT_HEADERS:
    case HTTP_CLIENT_EVT_SENT_BODY:
    case HTTP_CLIENT_EVT_HEADER_FIELD:
    case HTTP_CLIENT_EVT_HEADER_VAL:
    case HTTP_CLIENT_EVT_BODY_TOO_BIG:
    case HTTP_CLIENT_EVT_ERROR:
        break;
    }
}

/* --- Test functions --- */

static void test_http1_client_get_headers_cb(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    struct http_client_req req = {
        .method = HTTP_GET,
        .url = "/headers_cb",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 200, "Unexpected status code: %d", test_ctx.status_code);
    zassert_true(test_ctx.headers_received, "Headers not received");
    http_client_release(&client_ctx);
}

static void test_http1_client_get_no_resource(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    struct http_client_req req = {
        .method = HTTP_GET,
        .url = "/no_resource",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 404, "Unexpected status code: %d", test_ctx.status_code);
    http_client_release(&client_ctx);
}

static void test_http1_client_get_status_cb(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    struct http_client_req req = {
        .method = HTTP_GET,
        .url = "/status_cb",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 200, "Unexpected status code: %d", test_ctx.status_code);
    http_client_release(&client_ctx);
}

static void test_http1_client_post(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    const char *post_body = "This is a POST body.";
    struct http_client_req req = {
        .method = HTTP_POST,
        .url = "/post",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
        .payload = post_body,
        .payload_len = strlen(post_body),
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 200, "Unexpected status code: %d", test_ctx.status_code);
    http_client_release(&client_ctx);
}

static void test_http1_client_post_payload_cb(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    const char *post_body = "This is another POST body for payload callback.";
    struct http_client_req req = {
        .method = HTTP_POST,
        .url = "/post_payload_cb",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
        .payload = post_body,
        .payload_len = strlen(post_body),
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 200, "Unexpected status code: %d", test_ctx.status_code);
    http_client_release(&client_ctx);
}

/* The failing test: test_body_frag_len_chunked_te */
static void test_body_frag_len_chunked_te(void)
{
    struct http_client_ctx client_ctx;
    struct test_ctx test_ctx = {0};
    k_sem_init(&test_ctx.sem, 0, 1);

    http_client_init(&client_ctx, &test_ctx);
    http_client_set_cb(&client_ctx, http_client_test_cb);

    struct http_client_req req = {
        .method = HTTP_GET,
        .url = "/chunked",
        .host = SERVER_ADDR,
        .port = SERVER_PORT,
    };

    int ret = http_client_req(&client_ctx, &req, K_FOREVER, NULL);
    zassert_equal(ret, 0, "HTTP client request failed: %d", ret);

    k_sem_take(&test_ctx.sem, K_FOREVER);
    zassert_equal(test_ctx.status_code, 200, "Unexpected status code: %d", test_ctx.status_code);
    /* This is the assertion that failed. The fix ensures CHUNKED_BODY_SIZE
     * is correctly calculated to match the actual body length sent by the server.
     */
    zassert_equal(client_ctx.offset, CHUNKED_BODY_SIZE,
                  "Received body size %zu not equal to expected %zu",
                  client_ctx.offset, CHUNKED_BODY_SIZE);
    http_client_release(&client_ctx);
}

/* --- Test suite setup --- */
static void before_each(void *data)
{
    ARG_UNUSED(data);
    start_dummy_server();
}

static void after_each(void *data)
{
    ARG_UNUSED(data);
    stop_dummy_server();
}

ZTEST_SUITE(http_client, NULL, NULL, before_each, after_each, NULL);
ZTEST_SUITE(http_client_chunked_te, NULL, NULL, before_each, after_each, NULL);

/* Test cases for http_client suite */
ZTEST_USER(http_client, test_http1_client_get_headers_cb);
ZTEST_USER(http_client, test_http1_client_get_no_resource);
ZTEST_USER(http_client, test_http1_client_get_status_cb);
ZTEST_USER(http_client, test_http1_client_post);
ZTEST_USER(http_client, test_http1_client_post_payload_cb);

/* Test cases for http_client_chunked_te suite */
ZTEST_USER(http_client_chunked_te, test_body_frag_len_chunked_te);

/* Main function for the test runner */
void test_main(void)
{
    ztest_run_testsuite(http_client);
    ztest_run_testsuite(http_client_chunked_te);
}
